 "content": "def transform(grid):
    """Connect the 2 markers with a minimum-cost orthogonal backbone in color 3."""
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    if len(points) < 2:
        return out

    rows = sorted(r for r, _ in points)
    cols = sorted(c for _, c in points)
    # A backbone along the median row, with perpendicular branches to each marker.
    median_row = rows[(len(rows) - 1) // 2]
    horizontal_cost = max(cols) - min(cols) + sum(abs(r - median_row) for r, _ in points)
    # Or a backbone along the median column.
    median_col = cols[(len(cols) - 1) // 2]
    vertical_cost = max(rows) - min(rows) + sum(abs(c - median_col) for _, c in points)

    if horizontal_cost <= vertical_cost:  # observed tie-break favors a horizontal backbone
        for c in range(min(cols), max(cols) + 1):
            if out[median_row][c] == 0:
                out[median_row][c] = 3
        for r, c in points:
            step = 1 if median_row >= r else -1
            for rr in range(r, median_row + step, step):
                if out[rr][c] == 0:
                    out[rr][c] = 3
    else:
        for r in range(min(rows), max(rows) + 1):
            if out[r][median_col] == 0:
                out[r][median_col] = 3
        for r, c in points:
            step = 1 if median_col >= c else -1
            for cc in range(c, median_col + step, step):
                if out[r][cc] == 0:
                    out[r][cc] = 3
    return out
